public void appendToXML(XmlElement _parentNode)
{
    recordLineTag = MobConstants::SearchResult();
    super(_parentNode);
}

public str parmImageId ( str _imageId = imageID)
{
    imageID = _imageId;        
    return imageID;
}

protected void setXML()
{
    XmlElement      destination = resultXml.getElementsByTagName('responseData').item(0);

    this.appendToXML(destination);
}

public void convertFieldsToMap()
{

    fieldsToAdd.insert('imageId', fieldsToAdd.exists('imageId') ? fieldsToAdd.lookup('imageId') : imageId);

    super();
}

public void initFromCommon(XmlDocument _resultXml, Common _common, int _sorting, MobOrderTypes _orderType = '', MobPageID _pageId = '')
{
    Container            fields = TFMXMLFormat::fieldsFromCommon(_common).pack();
    super(_resultXml, _common, _sorting, _orderType, _pageId);
    displayLine1    = (conLen(fields) > 3 ? conPeek(fields,4) : '') + ' : ' + (conLen(fields) > 4 ? conPeek(fields,5) : '');
    displayLine2    = (conLen(fields) > 5 ? conPeek(fields,6) : '') + ' : ' + (conLen(fields) > 6 ? conPeek(fields,7) : '');
    displayLine3    = (conLen(fields) > 7 ? conPeek(fields,8) : '') + ' : ' + (conLen(fields) > 8 ? conPeek(fields,9) : '');

}
